-- 021_insert_murcia_centers.sql
-- Inserta los 52 centros de educacion infantil (0-3 anos) del termino
-- municipal de Murcia (capital + pedanias) investigados y humanizados en
-- este sprint: 38 guarderia (privados) + 14 escuela-infantil (7 Escuelas
-- Infantiles Municipales del Ayuntamiento de Murcia + 7 publicas de
-- titularidad autonomica).
-- Fuente: data/enrichment/murcia-centers.json (generado 2026-07-12).
-- Fuente primaria de datos: API oficial mapaescolar-api de la Comunidad
-- Autonoma de la Region de Murcia (CARM), dataset "Sedes de los Centros
-- Educativos de la Region de Murcia" (datosabiertos.regiondemurcia.es),
-- complementada con informajoven.org (Ayuntamiento de Murcia, para las 7
-- Escuelas Infantiles Municipales) y con las webs oficiales de 9 centros
-- privados verificados individualmente. Ver docs/data-sources-murcia.md.
--
-- Igual que en Valencia, ninguna fuente disponible incluye distritos
-- formales de la capital de Murcia, por lo que district queda NULL en los
-- 52 centros; neighborhood_barrio recoge la pedania para los 25 centros
-- situados fuera de la capital.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por
-- RLS hasta cambiarlos a 'published' manualmente, igual que se hizo con
-- Madrid, Barcelona y Valencia).
-- No toca ningun centro de Madrid, Barcelona ni Valencia. No borra ni
-- modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar. NO EJECUTADO por el
-- agente que lo genero.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "murcia" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('murcia', 'Murcia', 'Murcia', 'Región de Murcia')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
('bambi-murcia', 'Bambi', 'guarderia', 'privado', 'Calle La Seda, Nº 1 - Edif. Madrid', '30009', 'murcia', 'Murcia', NULL, NULL, NULL, 37.990504978224635, -1.1423741094768047, '968292806', 'belen70mz@gmail.com', NULL, 0, 36, NULL, '{}'::text[], 'Bambi aparece registrada en el mapa escolar de la Región de Murcia como centro privado de educación infantil, con dirección en Calle La Seda, Nº 1 - Edif. Madrid, 30009, en Murcia. Atiende a niños de 0 a 3 años. Para conocer horarios, servicios y disponibilidad de plazas, lo recomendable es ponerse en contacto con el centro.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado Bambi?","answer":"El centro se encuentra en Calle La Seda, Nº 1 - Edif. Madrid, 30009, en Murcia."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada, según el mapa escolar de la Consejería de Educación de la Región de Murcia."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 968292806 o escribir a belen70mz@gmail.com."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del mapa escolar de la Consejería de Educación de la Región de Murcia. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('futurines-s-l-l-murcia', 'Futurines, S.l.l.', 'guarderia', 'privado', 'Avenida Joven Futura, 29, Bajo (Espinardo)', '30100', 'murcia', 'Murcia', NULL, NULL, NULL, 38.00329802557826, -1.1587702855467796, '637314864', 'newfuturines1@gmail.com', NULL, 0, 36, NULL, '{}'::text[], 'Con dirección en Avenida Joven Futura, 29, Bajo (Espinardo), 30100, en Murcia, Futurines, S.l.l. es una guardería de titularidad privada que atiende el primer ciclo de educación infantil (0-3 años). El mapa escolar de la Consejería de Educación no detalla servicios adicionales, por lo que recomendamos confirmarlos directamente con el centro.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado Futurines, S.l.l.?","answer":"El centro se encuentra en Avenida Joven Futura, 29, Bajo (Espinardo), 30100, en Murcia."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada, según el mapa escolar de la Consejería de Educación de la Región de Murcia."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 637314864 o escribir a newfuturines1@gmail.com."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del mapa escolar de la Consejería de Educación de la Región de Murcia. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('virgen-de-la-fuensanta-murcia', 'Virgen de la Fuensanta', 'guarderia', 'privado', 'Paseo de las Moreras, s/n (Espinardo)', '30100', 'murcia', 'Murcia', NULL, NULL, NULL, 37.94745493680239, -1.1660741083323956, '968846074', NULL, NULL, 0, 36, NULL, '{}'::text[], 'Virgen de la Fuensanta es una guardería privada situada en Paseo de las Moreras, s/n (Espinardo), 30100, en Murcia, dedicada a niños de 0 a 3 años según consta en el mapa escolar de la Región de Murcia. Esta ficha se limita a los datos confirmados en la fuente oficial; para conocer el resto de detalles, recomendamos contactar con el centro.', NULL, '{}'::text[], '[{"question":"¿Dónde está ubicado Virgen de la Fuensanta?","answer":"El centro se encuentra en Paseo de las Moreras, s/n (Espinardo), 30100, en Murcia."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada, según el mapa escolar de la Consejería de Educación de la Región de Murcia."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 968846074."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del mapa escolar de la Consejería de Educación de la Región de Murcia. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros', '{}'::text[], '2026-07-12'::date, 'unverified', 'medium', '{}'::jsonb, 'draft'),
('ntra-sra-de-la-fuensanta-murcia', 'Ntra. Sra. de la Fuensanta', 'escuela-infantil', 'publico', 'Calle Renacimiento, s/n', '30012', 'murcia', 'Murcia', NULL, NULL, NULL, 37.97178299166262, -1.1248891241848469, '968254230', '30000717@murciaeduca.es', NULL, 4, 36, 'Lunes a viernes de 8:15 a 16:00 h, con servicio de matinal desde las 7:30 h', ARRAY['comedor','servicio-madrugadores']::text[], 'Ntra. Sra. de la Fuensanta, en Calle Renacimiento, s/n, 30012, es una escuela infantil de titularidad pública dependiente del Ayuntamiento de Murcia. Como el resto de la red municipal, atiende a niños de 0 a 3 años y dispone de comedor y matinal. Recomendamos consultar el calendario de preinscripción municipal para conocer plazas disponibles.', 'Ntra. Sra. de la Fuensanta es una de las siete escuelas infantiles municipales que gestiona el Ayuntamiento de Murcia a través de su Patronato de Escuelas Infantiles, con sede en Calle Renacimiento, s/n, 30012.

Como el resto de la red municipal (que suma 6 escuelas más, repartidas entre la capital y varias pedanías del término municipal), atiende el primer ciclo de educación infantil: niños de 4 meses a 3 años, organizados en aulas nido para los bebés de menor edad y aulas de 1 y 2 años para el resto. El horario habitual es de 8:15 a 16:00 h, con posibilidad de entrada anticipada desde las 7:30 h mediante el servicio de matinal, y todas las escuelas cuentan con servicio de comedor con menús adaptados a estas edades.

El acceso a una plaza no es directo: se tramita cada curso mediante un proceso de admisión municipal con baremación pública (empadronamiento, situación laboral y familiar, entre otros criterios), y la demanda suele superar la oferta, por lo que conviene informarse con antelación sobre plazos de preinscripción. Para más información sobre plazas y calendario, el Patronato de Escuelas Infantiles del Ayuntamiento de Murcia atiende en la calle Amberes, 3.', '{}'::text[], '[{"question":"¿Dónde está ubicado Ntra. Sra. de la Fuensanta?","answer":"El centro se encuentra en Calle Renacimiento, s/n, 30012, en Murcia."},{"question":"¿Qué edades atiende esta escuela infantil municipal?","answer":"Atiende a niños de 4 meses a 3 años, organizados en aulas nido para los más pequeños y aulas de 1 y 2 años para el resto."},{"question":"¿Es un centro público o privado?","answer":"Es un centro público, una de las siete escuelas infantiles municipales gestionadas por el Ayuntamiento de Murcia a través de su Patronato de Escuelas Infantiles."},{"question":"¿Tiene servicio de comedor y horario ampliado?","answer":"Sí. Todas las escuelas infantiles municipales de Murcia ofrecen comedor y servicio de matinal desde las 7:30 h, con horario lectivo de 8:15 a 16:00 h."},{"question":"¿Cómo se solicita una plaza?","answer":"El acceso se tramita mediante el proceso anual de admisión del Ayuntamiento de Murcia, con baremación pública. Dada la alta demanda de la red municipal, conviene informarse con antelación sobre los plazos de preinscripción."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 968254230 o escribir a 30000717@murciaeduca.es. También puedes dirigirte al Patronato de Escuelas Infantiles del Ayuntamiento de Murcia (C/ Amberes, 3) para consultas sobre el proceso de admisión."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros', ARRAY['https://www.informajoven.org/info/educacion/B_9_2.asp']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
('los-molinos-murcia', 'Los Molinos', 'guarderia', 'privado', 'Calle Jumilla, 11', '30002', 'murcia', 'Murcia', NULL, NULL, NULL, 37.98118396662176, -1.1324630118906498, '968221411', 'escuelainfantillosmolinos@gmail.com', 'https://www.escuelainfantil-losmolinos.com/', 0, 36, 'Horario ampliado de 7:30 a 17:00 h', ARRAY['comedor','cocina-propia','horario-ampliado','patio-exterior','psicomotricidad','actividades-extraescolares']::text[], 'Los Molinos, en Calle Jumilla, 11, 30002, en Murcia, es un centro privado de primer ciclo de educación infantil. Su web oficial confirma cocina propia, dos patios de juego y psicomotricidad. Antes de solicitar plaza, conviene confirmar horarios y disponibilidad directamente con el centro.', 'Los Molinos es un centro privado de educación infantil de primer ciclo situado en Calle Jumilla, 11, 30002, en Murcia, dedicado a niños de 0 a 3 años. Su presencia en el mapa escolar de la Consejería de Educación de la Región de Murcia confirma su autorización como centro de esta etapa educativa.

Según la información publicada en su propia web, el centro ofrece: Cocina propia con menús adaptados por edad, dos patios de juego, psicomotricidad, visitas y actividades acuáticas en verano. El horario habitual es: horario ampliado de 7:30 a 17:00 h.

Estos datos proceden directamente de la web oficial del centro, por lo que pueden variar de un curso a otro. Antes de solicitar plaza, recomendamos confirmar con Los Molinos la disponibilidad, precios y condiciones actualizadas de matrícula.', '{}'::text[], '[{"question":"¿Dónde está ubicado Los Molinos?","answer":"El centro se encuentra en Calle Jumilla, 11, 30002, en Murcia."},{"question":"¿Qué edades atiende este centro?","answer":"Es un centro de educación infantil de primer ciclo, dirigido a niños de 0 a 3 años."},{"question":"¿Es un centro público o privado?","answer":"Es un centro de titularidad privada, según el mapa escolar de la Consejería de Educación de la Región de Murcia."},{"question":"¿Tiene servicio de comedor?","answer":"Sí, el centro confirma en su web que dispone de servicio de comedor con cocina propia."},{"question":"¿Cómo puedo contactar con el centro?","answer":"Puedes llamar al teléfono 968221411 o escribir a escuelainfantillosmolinos@gmail.com, o visitar https://www.escuelainfantil-losmolinos.com/."},{"question":"¿Está verificada la información de esta ficha?","answer":"Los datos proceden del mapa escolar de la Consejería de Educación de la Región de Murcia y de la web oficial del centro. Si representas este centro, puedes solicitar una actualización o reclamar la ficha."}]'::jsonb, false, false, '{}'::jsonb, '{}'::text[], 'https://mapaescolar.murciaeduca.es/mapaescolar-api/api/centros', ARRAY['https://www.escuelainfantil-losmolinos.com/']::text[], '2026-07-12'::date, 'unverified', 'high', '{}'::jsonb, 'draft'),
